input.function:
() => {
  const links = Array.from(document.querySelectorAll('a'));
  const matches = links.filter(a => a.textContent.trim() === 'FVINR');
  return matches.map(a => ({ text: a.textContent.trim(), href: a.href, outerHTML: a.outerHTML.slice(0, 300) }));
}

() => {
  const cells = Array.from(document.querySelectorAll('td, th'));
  const cell = cells.find(c => c.textContent.trim() === 'FVINR');
  if (!cell) return 'not found';
  const row = cell.closest('tr');
  const links = row ? Array.from(row.querySelectorAll('a')).map(a => a.href) : [];
  const text = row ? row.textContent : '';
  const html = row ? row.innerHTML.slice(0, 1500) : '';
  return { links, text, html };
}
